"""Institutional content grounded in Adore's existing public website."""

def build_about(crumb, button, icon, contact, artist_count):
    audiences = [
        ('Prefeituras e eventos públicos', 'Artistas para aniversários de cidades, festas municipais e festivais. Conte a data, o local e o perfil do público para consultar atrações e planejar a programação.', '/contrate/?tipo=prefeitura', 'Converse sobre a programação'),
        ('Igrejas, congressos e festivais gospel', 'Cantores, bandas e ministérios para encontros de louvor, celebrações e programações que fazem parte da vida da comunidade.', '/artistas/gospel/', 'Conheça o catálogo gospel'),
        ('Produtores, empresas e eventos privados', 'Atrações para festivais, convenções, confraternizações e festas. Conte o formato do evento para conversar sobre as possibilidades de contratação.', '/contrate/', 'Conte o seu projeto'),
    ]
    return f'''<div class="about-page">
<section class="about-opening"><div class="wrap">{crumb([('A Adore','')])}
<div class="about-opening-grid"><h1>Antes da primeira canção,<br>tem a <span>Adore.</span></h1><div class="about-opening-copy"><p>Você pensa no encontro.<br>A gente trabalha para o show acontecer.</p><p>Somos a Adore Shows. Trabalhamos na contratação de artistas para prefeituras, produtores, empresas e igrejas, com atendimento em todo o Brasil.</p><a class="text-link" href="#nossa-historia">Conheça a nossa história {icon('down')}</a></div></div>
<figure class="about-stage"><img src="/assets/hero/titas-live.jpg" alt="A banda Titãs em uma apresentação ao vivo" width="1200" height="900" fetchpriority="high"><figcaption>Titãs em cena. Banda presente no nosso catálogo.</figcaption></figure>
</div></section>
<section class="about-history" id="nossa-historia"><div class="wrap about-history-grid"><div class="about-history-copy"><h2>A história da Adore.</h2><p>Há mais de 15 anos, a Adore Shows trabalha no agenciamento de artistas e na contratação de shows. Com sede em Goiânia, atendemos prefeituras, produtores, empresas e igrejas em todo o país.</p><p>Nosso trabalho começa por entender o evento e o seu público. A partir daí, acompanhamos a contratação: consulta de agenda, proposta, contrato e alinhamento dos detalhes até a confirmação do show.</p></div><dl class="about-facts"><div><dt><span class="about-fact-prefix">Mais de</span><span class="about-fact-value">15 <span>anos</span></span></dt><dd>de atuação no mercado de shows</dd></div><div><dt><span class="about-fact-prefix">Mais de</span><span class="about-fact-value">5.000 <span>eventos</span></span></dt><dd>realizados ao longo da nossa trajetória</dd></div></dl></div></section>
<section class="about-gospel" id="nosso-catalogo"><div class="wrap about-gospel-grid"><div class="about-gospel-copy"><h2>Artistas de diferentes estilos.</h2><p>Sertanejo, forró, gospel, pagode, rock e outros gêneros fazem parte do nosso catálogo. A escolha da atração considera o público e a programação de cada evento.</p><p>Se você já tem um artista em mente, consultamos a agenda. Se ainda está escolhendo, conte a data, a cidade e o formato do evento. Nossa equipe apresenta as possibilidades para a sua programação.</p>{button('Explore todos os artistas','/artistas/','dark')}</div><div class="about-gospel-artists"><div class="about-voices"><a href="/lauana-prado/"><img src="/assets/artists/lauana-prado.webp" alt="" width="640" height="800" loading="lazy"><span>Lauana Prado</span></a><a href="/joao-gomes/"><img src="/assets/artists/joao-gomes.webp" alt="" width="640" height="800" loading="lazy"><span>João Gomes</span></a><a href="/aline-barros/"><img src="/assets/artists/aline-barros.webp" alt="" width="640" height="800" loading="lazy"><span>Aline Barros</span></a></div><p class="about-gospel-selection">Artistas do nosso catálogo, que reúne <strong>{artist_count} nomes em 10 segmentos.</strong></p><p class="about-catalog-note">Disponibilidade e condições de contratação mediante consulta.</p></div></div></section>
<section class="about-audiences"><div class="wrap"><div class="about-section-heading"><h2>O público muda.<br>A atenção continua.</h2><p>Cada evento tem seu contexto.<br>A contratação começa por entender o seu.</p></div><div class="about-audience-list">{''.join(f'<article><h3>{title}</h3><div><p>{copy}</p><a class="text-link" href="{href}">{label} {icon("diagonal")}</a></div></article>' for title,copy,href,label in audiences)}</div></div></section>
<section class="about-process"><div class="wrap process"><div class="process-intro"><h2>Da primeira conversa<br>ao show confirmado.</h2><p>Uma equipe para acompanhar as decisões e deixar claros os próximos passos.</p><a class="text-link" href="/contrate/">Fale sobre seu evento {icon('diagonal')}</a></div><ol class="steps"><li><div><h3>Começamos pelo seu projeto</h3><p>Você conta a cidade, a data, o formato e o artista desejado. Se ainda estiver escolhendo, fale sobre o público e a proposta do encontro.</p></div></li><li><div><h3>Consultamos e apresentamos a proposta</h3><p>Verificamos a disponibilidade e as condições de apresentação para você avaliar a contratação.</p></div></li><li><div><h3>Formalizamos e alinhamos os detalhes</h3><p>Com a proposta aprovada, seguimos para o contrato e o alinhamento da apresentação. A equipe acompanha você até a confirmação do show.</p></div></li></ol></div></section>
</div>{contact()}'''
